using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();
builder.Services.AddSingleton<TicketModelTrainer>();

// Train model at startup so the file is available for the pool
var dataPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "tickets.csv");
var modelPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "model.zip");
TrainModel(dataPath, modelPath);

builder.Services.AddPredictionEnginePool<TicketData, TicketPrediction>()
    .FromFile(modelPath);

var app = builder.Build();
app.MapControllers();
app.Run();

static void TrainModel(string dataPath, string modelPath)
{
    var mlContext = new MLContext(seed: 42);

    var data = mlContext.Data.LoadFromTextFile<TicketData>(
        dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

    var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.3, seed: 42);

    var pipeline = mlContext.Transforms.Text.FeaturizeText("SubjectFeatures", nameof(TicketData.Subject))
        .Append(mlContext.Transforms.Text.FeaturizeText("DescriptionFeatures", nameof(TicketData.Description)))
        .Append(mlContext.Transforms.Concatenate("Features", "SubjectFeatures", "DescriptionFeatures", nameof(TicketData.Priority)))
        .Append(mlContext.Transforms.Conversion.MapValueToKey("Label", nameof(TicketData.Category)))
        .Append(mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy("Label", "Features"))
        .Append(mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

    var model = pipeline.Fit(split.TrainSet);

    // Evaluate and print metrics
    var predictions = model.Transform(split.TestSet);
    var metrics = mlContext.MulticlassClassification.Evaluate(predictions);

    Console.WriteLine("=== Model Evaluation Metrics ===");
    Console.WriteLine($"  MacroAccuracy:    {metrics.MacroAccuracy:F4}");
    Console.WriteLine($"  MicroAccuracy:    {metrics.MicroAccuracy:F4}");
    Console.WriteLine($"  LogLoss:          {metrics.LogLoss:F4}");
    Console.WriteLine($"  LogLossReduction: {metrics.LogLossReduction:F4}");

    mlContext.Model.Save(model, data.Schema, modelPath);
    Console.WriteLine($"  Model saved to:   {modelPath}");
}

